declarations.type:
∀ {E : Type} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] [ProperSpace E] {G : Type}
  [inst_3 : NormedAddCommGroup G] [inst_4 : NormedSpace ℝ G] [CompleteSpace G] (F : ℝ × E → G),
  ContDiff ℝ (↑⊤) F → ContDiff ℝ ↑⊤ fun p => ∫ (s : ℝ) in 0..1, F (s, p)

∀ {E : Type} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] [ProperSpace E] (n : ℕ) {G : Type}
  [inst_3 : NormedAddCommGroup G] [inst_4 : NormedSpace ℝ G] [CompleteSpace G] (F : ℝ × E → G),
  ContDiff ℝ (↑⊤) F → ContDiff ℝ ↑n fun p => ∫ (s : ℝ) in 0..1, F (s, p)

∀ {L b : ℝ} {terms : ℕ} {field : ℕ → Fin terms → Breakdown.Space → Breakdown.Space}
  {isTest : ∀ (n : ℕ) (l : Fin terms), Breakdown.IsTestField (field n l)}
  {support : ∀ (n : ℕ) (l : Fin terms), tsupport (field n l) ⊆ Metric.closedBall 0 b}
  {weight : ℕ → Fin terms → C(↑(Set.Icc 0 L), ℝ)}
  {bound : ∃ C, ∀ (n : ℕ) (l : Fin terms), ‖Breakdown.Freq.embedX (field n l)‖ ≤ C ∧ ‖weight n l‖ ≤ C} {terms_1 : ℕ}
  {field_1 : ℕ → Fin terms_1 → Breakdown.Space → Breakdown.Space}
  {isTest_1 : ∀ (n : ℕ) (l : Fin terms_1), Breakdown.IsTestField (field_1 n l)}
  {support_1 : ∀ (n : ℕ) (l : Fin terms_1), tsupport (field_1 n l) ⊆ Metric.closedBall 0 b}
  {weight_1 : ℕ → Fin terms_1 → C(↑(Set.Icc 0 L), ℝ)}
  {bound_1 : ∃ C, ∀ (n : ℕ) (l : Fin terms_1), ‖Breakdown.Freq.embedX (field_1 n l)‖ ≤ C ∧ ‖weight_1 n l‖ ≤ C},
  { terms := terms, field := field, isTest := isTest, support := support, weight := weight, bound := bound } =
      { terms := terms_1, field := field_1, isTest := isTest_1, support := support_1, weight := weight_1,
        bound := bound_1 } →
    terms = terms_1 ∧ field ≍ field_1 ∧ weight ≍ weight_1
